class OAuth2(SecurityBase):
    type_: SecuritySchemeType = Field(default=SecuritySchemeType.oauth2, alias="type")
    flows: OAuthFlows
    scopes: Optional[Set[str]] = None

    def __init__(self, **data: Any):
        super().__init__(**data)
        self.scopes = self._calculate_scopes()

    def _calculate_scopes(self) -> Set[str]:
        all_scopes = set()
        if self.flows:
            for flow_name, flow_obj in self.flows.__dict__.items():
                if isinstance(flow_obj, OAuthFlow):
                    all_scopes.update(flow_obj.scopes.keys())
        return all_scopes

