from typing import Set, Any
from fastapi.openapi.models import (
    OAuth2, OAuthFlow, OAuthFlowPassword, OAuthFlowImplicit, SecuritySchemeType
)

def test_oauth2_scope_aggregation():
    # 1. Setup flows with different scopes
    password_flow = OAuthFlowPassword(
        tokenUrl="http://example.com/token",
        scopes={"read": "Read access", "write": "Write access"}
    )
    implicit_flow = OAuthFlowImplicit(
        authorizationUrl="http://example.com/auth",
        scopes={"openid": "OpenID scope", "profile": "Profile scope"}
    )

    # 2. Create OAuth2 scheme with multiple flows
    oauth2 = OAuth2(
        type_=SecuritySchemeType.oauth2,
        flows={
            "password": password_flow,
            "implicit": implicit_flow
        }
    )

    # 3. Verify scopes aggregation
    expected_scopes = {"read", "write", "openid", "profile"}
    actual_scopes = oauth2.scopes

    print(f"Expected scopes: {expected_scopes}")
    print(f"Actual scopes: {actual_scopes}")

    assert actual_scopes is not None
    assert actual_scopes == expected_scopes, f"Scope mismatch. Expected {expected_scopes}, got {actual_scopes}"
    print("Test passed: All scopes correctly aggregated.")

test_oauth2_scope_aggregation()
